const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let STATE=null, HUBSTATE=null, activeHubIdent=null, selectedUpgrade=null, selectedAircraft=null, cockpitMap=null, hubMap=null, worldMap=null;
let hubUpgradeMarkers=[], hubAssetMarkers=[], hubTrafficMarkers=[], worldAircraftMarkers=new Map(), worldRealMarkers=[], worldMajorLoaded=false, weatherEnabled=true, airportLayerEnabled=true, routesEnabled=true, spinTimer=null;
let hubSurfaceLines=[], hubGatePoints=[], hubSurfaceFeatures=[], hubSurfaceSource='fallback', WORLD_MAJOR_AIRPORTS=[], aiWorldFlights=[], aiWorldMarkers=[];
let marketOffset=0, marketQuery='', marketManufacturer='', marketCommercial=true, routeDestination=null, extraHubSelected=null, logoData='';
const SAT_STYLE={version:8,sources:{sat:{type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,attribution:'Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics, and the GIS User Community'}},layers:[{id:'sat',type:'raster',source:'sat'}]};
const money=v=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v||0);
const fmt=n=>new Intl.NumberFormat('fr-FR').format(n||0);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
async function api(url,opt={}){const r=await fetch(url,opt);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||d.reason||'Erreur serveur');return d}
function debounce(fn,ms=220){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}}
function nav(name){$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));if(name==='hub'&&hubMap)setTimeout(()=>hubMap.resize(),50);if(name==='world'&&worldMap)setTimeout(()=>worldMap.resize(),50);window.scrollTo(0,0)}
$$('[data-nav]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.nav)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.go)));$$('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close)?.classList.remove('open')));

function gcPoints(a,b,n=64){const out=[];for(let i=0;i<=n;i++){const t=i/n;const p1=a.lat*Math.PI/180,l1=a.lon*Math.PI/180,p2=b.lat*Math.PI/180,l2=b.lon*Math.PI/180;const A=[Math.cos(p1)*Math.cos(l1),Math.cos(p1)*Math.sin(l1),Math.sin(p1)],B=[Math.cos(p2)*Math.cos(l2),Math.cos(p2)*Math.sin(l2),Math.sin(p2)];let dot=Math.max(-1,Math.min(1,A[0]*B[0]+A[1]*B[1]+A[2]*B[2])),w=Math.acos(dot);let V;if(w<1e-9)V=A;else{const s=Math.sin(w),a1=Math.sin((1-t)*w)/s,b1=Math.sin(t*w)/s;V=[a1*A[0]+b1*B[0],a1*A[1]+b1*B[1],a1*A[2]+b1*B[2]]}out.push([Math.atan2(V[1],V[0])*180/Math.PI,Math.atan2(V[2],Math.hypot(V[0],V[1]))*180/Math.PI])}return out}
function destinationPoint(lat,lon,bearing,dist){const R=6371000,b=bearing*Math.PI/180,p1=lat*Math.PI/180,l1=lon*Math.PI/180,d=dist/R,p2=Math.asin(Math.sin(p1)*Math.cos(d)+Math.cos(p1)*Math.sin(d)*Math.cos(b)),l2=l1+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(p1),Math.cos(d)-Math.sin(p1)*Math.sin(p2));return [((l2*180/Math.PI+540)%360)-180,p2*180/Math.PI]}

function renderHeader(){if(!STATE)return;$('#companyName').textContent=(STATE.profile.logo_text||STATE.user.company_name).toUpperCase();$('#cash').textContent=money(STATE.user.cash);$('#rep').textContent=STATE.user.reputation+' ★';$('#fleetCount').textContent=STATE.aircraft.length;const h=STATE.hubs.find(x=>x.is_primary)||STATE.hubs[0];$('#activeHubLabel').textContent=h?h.airport.code:'—';document.documentElement.style.setProperty('--company-primary',STATE.profile.primary_color);document.documentElement.style.setProperty('--company-accent',STATE.profile.accent_color)}

async function loadState(){try{STATE=await api('/api/state');renderHeader();renderHubSelector();renderOwnedHubs();renderFleet();renderRoutes();syncWorldRoutes();syncWorldAircraft();syncIdentity();updateCockpit()}catch(e){if(e.message.includes('connect'))location.href='/login';else toast(e.message)}}

// ---------- HUB VIEW ----------
function initHubMap(){hubMap=new maplibregl.Map({container:'hubMap',style:SAT_STYLE,center:[2.55,49.01],zoom:13,pitch:58,bearing:28,maxPitch:82});hubMap.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');hubMap.on('load',()=>{if(activeHubIdent)loadHub(activeHubIdent)})}
function renderHubSelector(){const sel=$('#hubSelector');if(!STATE||!sel)return;const old=activeHubIdent;sel.innerHTML=STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('');if(!activeHubIdent){activeHubIdent=(STATE.hubs.find(h=>h.is_primary)||STATE.hubs[0])?.ident}sel.value=activeHubIdent||'';if(old!==activeHubIdent&&activeHubIdent)loadHub(activeHubIdent)}
$('#hubSelector').addEventListener('change',e=>{activeHubIdent=e.target.value;loadHub(activeHubIdent)});$('#hubResetView').addEventListener('click',()=>focusHub());
$('#toggleUpgrades').addEventListener('click',e=>{e.currentTarget.classList.toggle('active');const on=e.currentTarget.classList.contains('active');hubUpgradeMarkers.forEach(m=>m.getElement().style.display=on?'grid':'none')});
$('#toggleTraffic').addEventListener('click',e=>{e.currentTarget.classList.toggle('active');const on=e.currentTarget.classList.contains('active');hubTrafficMarkers.forEach(m=>m.getElement().style.display=on?'grid':'none')});
function focusHub(){if(!HUBSTATE||!hubMap)return;hubMap.easeTo({center:[HUBSTATE.airport.lon,HUBSTATE.airport.lat],zoom:HUBSTATE.airport.type==='large_airport'?14:HUBSTATE.airport.type==='medium_airport'?13.5:13,pitch:62,bearing:25,duration:1300})}
async function loadHub(ident){if(!hubMap||!hubMap.loaded())return;try{HUBSTATE=await api('/api/hub/'+encodeURIComponent(ident));$('#hubTitle').textContent=`${HUBSTATE.airport.code} · ${HUBSTATE.airport.name}`;$('#hubMeta').textContent=`${HUBSTATE.airport.municipality||''} · Hub niv. ${HUBSTATE.hub.level} · ${HUBSTATE.airport.runway_count} piste(s)`;drawHubRunways();await loadHubSurfaceNetwork();drawHubUpgrades();focusHub();await refreshHubTraffic()}catch(e){toast(e.message)}}
function drawHubRunways(){if(!hubMap||!HUBSTATE)return;if(hubMap.getLayer('hub-runways'))hubMap.removeLayer('hub-runways');if(hubMap.getSource('hub-runways'))hubMap.removeSource('hub-runways');const features=HUBSTATE.airport.runways.filter(r=>r.le_lon!=null&&r.he_lon!=null).map(r=>({type:'Feature',geometry:{type:'LineString',coordinates:[[r.le_lon,r.le_lat],[r.he_lon,r.he_lat]]},properties:{name:(r.le_ident||'')+' / '+(r.he_ident||''),length:r.length_ft||0}}));hubMap.addSource('hub-runways',{type:'geojson',data:{type:'FeatureCollection',features}});hubMap.addLayer({id:'hub-runways',type:'line',source:'hub-runways',paint:{'line-color':'#6ee7ff','line-width':['interpolate',['linear'],['zoom'],11,1,16,4],'line-opacity':.72}})}
function clearMarkers(arr){arr.forEach(m=>m.remove());arr.length=0}

async function loadHubSurfaceNetwork(){
  if(!hubMap||!HUBSTATE)return;
  ['hub-aprons','hub-taxiways','hub-osm-runways','hub-gates'].forEach(id=>hubMap.getLayer(id)&&hubMap.removeLayer(id));
  if(hubMap.getSource('hub-surface'))hubMap.removeSource('hub-surface');
  hubSurfaceLines=[];hubGatePoints=[];
  try{
    const geo=await api('/api/hub/'+encodeURIComponent(activeHubIdent)+'/surface-network');hubSurfaceSource=geo.source||'surface';
    hubMap.addSource('hub-surface',{type:'geojson',data:geo});
    hubMap.addLayer({id:'hub-aprons',type:'fill',source:'hub-surface',filter:['==',['get','kind'],'apron'],paint:{'fill-color':'#4fa3c7','fill-opacity':.10,'fill-outline-color':'#8bdcff'}});
    hubMap.addLayer({id:'hub-taxiways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'taxiway'],paint:{'line-color':'#ffd35f','line-width':['interpolate',['linear'],['zoom'],11,.7,16,2.7],'line-opacity':.68}});
    hubMap.addLayer({id:'hub-osm-runways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'runway'],paint:{'line-color':'#8eeaff','line-width':['interpolate',['linear'],['zoom'],11,1,16,4.5],'line-opacity':.75}});
    hubMap.addLayer({id:'hub-gates',type:'circle',source:'hub-surface',filter:['in',['get','kind'],['literal',['gate','parking_position']]],paint:{'circle-radius':['interpolate',['linear'],['zoom'],12,1.5,17,4.2],'circle-color':'#f4f8fb','circle-opacity':.72,'circle-stroke-color':'#0b2330','circle-stroke-width':1}});
    (geo.features||[]).forEach(f=>{const k=f.properties?.kind;if(f.geometry?.type==='LineString'&&(k==='taxiway'||k==='runway'))hubSurfaceLines.push({kind:k,coords:f.geometry.coordinates});if(f.geometry?.type==='Point'&&(k==='gate'||k==='parking_position'))hubGatePoints.push(f.geometry.coordinates)});
    $('#hubMeta').textContent+=` · réseau sol ${hubSurfaceSource.includes('OpenStreetMap')?'OSM':'pistes'}`;
  }catch(e){console.warn('Surface network unavailable',e)}
}
function pointOnLine(coords,t){if(!coords||coords.length<2)return null;const seg=(coords.length-1)*Math.max(0,Math.min(1,t)),i=Math.min(coords.length-2,Math.floor(seg)),f=seg-i,a=coords[i],b=coords[i+1];return[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}

function drawHubUpgrades(){clearMarkers(hubUpgradeMarkers);HUBSTATE.nodes.forEach(n=>{const el=document.createElement('button');el.className='hub-upgrade-marker '+n.state;el.textContent=n.level?String(n.level):'+';el.title=n.name;el.addEventListener('click',()=>inspectUpgrade(n));const m=new maplibregl.Marker({element:el,anchor:'center'}).setLngLat([n.lon,n.lat]).addTo(hubMap);hubUpgradeMarkers.push(m)})}
function inspectUpgrade(n){selectedUpgrade=n;const c=$('#hubInspectorContent');let prereq=n.prereq?HUBSTATE.nodes.find(x=>x.code===n.prereq):null;c.innerHTML=`<span class="inspector-tag">${n.cat.toUpperCase()}</span><h2 class="inspector-title">${n.name}</h2><p class="muted">${n.desc}</p><div class="level-box"><div><span>NIVEAU</span><strong>${n.level} / ${n.max}</strong></div><div><span>PROCHAIN INVESTISSEMENT</span><strong>${n.level>=n.max?'MAX':money(n.price)}</strong></div></div>${!n.available&&prereq?`<div class="prereq">Prérequis : ${prereq.name} niveau 1</div>`:''}<div class="stat-row"><span>État</span><b>${n.state==='active'?'Actif':n.state==='available'?'Disponible':'Verrouillé'}</b></div><button class="primary" id="buyUpgrade" ${n.level>=n.max||!n.available?'disabled':''}>${n.level>=n.max?'Niveau maximum':n.level?'Améliorer':'Construire / débloquer'}</button>`;$('#hubInspector').classList.add('open');$('#buyUpgrade')?.addEventListener('click',async()=>{try{await api('/api/hub/upgrade',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ident:activeHubIdent,code:n.code})});toast(`${n.name} amélioré`);await loadState();await loadHub(activeHubIdent)}catch(e){toast(e.message)}})}
function inspectGroundPlane(p){$('#hubInspectorContent').innerHTML=`<span class="inspector-tag">TON AVION</span><h2 class="inspector-title">${p.tail}</h2><div class="owned-plane-card"><div class="tail">${p.type}</div><small>${p.status}</small></div><button class="primary" id="watchGroundPlane">Vue cockpit / observation</button>`;$('#hubInspector').classList.add('open');$('#watchGroundPlane').addEventListener('click',()=>openCockpit(p.aircraft_id))}
async function refreshHubTraffic(){if(!HUBSTATE||!hubMap)return;clearMarkers(hubTrafficMarkers);const a=HUBSTATE.airport;const own=HUBSTATE.own_ground_aircraft||[];own.forEach((p,i)=>{const el=document.createElement('div');el.className='aircraft-marker';el.innerHTML='✈';el.style.transform=`rotate(${(i*37)%360}deg)`;el.addEventListener('click',()=>inspectGroundPlane(p));const pos=hubGatePoints.length?hubGatePoints[i%hubGatePoints.length]:destinationPoint(a.lat,a.lon,35+i*42,170+i*45);const m=new maplibregl.Marker({element:el}).setLngLat(pos).addTo(hubMap);hubTrafficMarkers.push(m);animateGroundMarker(m,a,1000+i,'own')});
  let live={states:[]};try{live=await api('/api/live-traffic?ident='+encodeURIComponent(activeHubIdent))}catch{};
  (live.states||[]).slice(0,45).forEach(s=>{const el=document.createElement('div');el.className='ai-plane-marker';el.textContent='✈';el.style.transform=`rotate(${s.heading||0}deg)`;el.title=(s.callsign||'Trafic réel')+(live.source?` · ${live.source}`:'');const m=new maplibregl.Marker({element:el}).setLngLat([s.lon,s.lat]).addTo(hubMap);hubTrafficMarkers.push(m)});
  const count=Math.min(36,HUBSTATE.traffic_density||12);for(let i=0;i<count;i++){const type=i%5===0?'✈':i%4===0?'▰':'•';const el=document.createElement('div');el.className=type==='✈'?'ai-plane-marker':'vehicle-marker';el.textContent=type==='•'?(i%2?'🚚':'🚌'):type;const r=250+(i%8)*95,b=(i*47)%360,pos=destinationPoint(a.lat,a.lon,b,r);const m=new maplibregl.Marker({element:el}).setLngLat(pos).addTo(hubMap);hubTrafficMarkers.push(m);animateGroundMarker(m,a,i,type==='✈'?'plane':'vehicle')} }
function animateGroundMarker(marker,a,seed,kind='ai'){
  const start=performance.now();
  const usable=hubSurfaceLines.filter(x=>kind==='vehicle'?x.kind==='taxiway':true);
  const path=usable.length?usable[seed%usable.length]:null;
  const radius=240+(seed%9)*90,speed=.000035+(seed%7)*.000009;
  function tick(t){
    if(!hubTrafficMarkers.includes(marker))return;
    if(path&&path.coords.length>1){let p=((t-start)*speed+(seed*.137))%2;if(p>1)p=2-p;const pt=pointOnLine(path.coords,p);if(pt)marker.setLngLat(pt)}
    else{const angle=(seed*41+(t-start)*speed*180/Math.PI)%360;marker.setLngLat(destinationPoint(a.lat,a.lon,angle,radius))}
    requestAnimationFrame(tick)
  }requestAnimationFrame(tick)
}
setInterval(()=>{if(document.querySelector('[data-view="hub"]').classList.contains('active'))refreshHubTraffic()},20000);

// ---------- WORLD GLOBE ----------
function initWorldMap(){worldMap=new maplibregl.Map({container:'worldMap',style:SAT_STYLE,center:[10,25],zoom:1.35,pitch:18,bearing:0,maxPitch:80});worldMap.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');worldMap.on('load',async()=>{worldMap.setProjection({type:'globe'});await loadMajorAirports();await addWeather();syncWorldRoutes();syncWorldAircraft()});worldMap.on('click','major-airports',e=>inspectWorldAirport(e.features[0].properties));worldMap.on('click','owned-hubs',e=>inspectWorldAirport(e.features[0].properties))}
async function loadMajorAirports(){if(worldMajorLoaded)return;const items=await api('/api/airports/major?limit=900');WORLD_MAJOR_AIRPORTS=items;const features=items.map(a=>({type:'Feature',geometry:{type:'Point',coordinates:[a.lon,a.lat]},properties:{ident:a.ident,code:a.code,name:a.name,type:a.type,country:a.country,municipality:a.municipality||''}}));worldMap.addSource('major-airports',{type:'geojson',data:{type:'FeatureCollection',features}});worldMap.addLayer({id:'major-airports',type:'circle',source:'major-airports',paint:{'circle-radius':['interpolate',['linear'],['zoom'],1,1.3,5,4.5],'circle-color':'#bfd8e8','circle-opacity':['interpolate',['linear'],['zoom'],1,.28,4,.75],'circle-stroke-color':'#08202d','circle-stroke-width':1}});worldMajorLoaded=true;initWorldAITraffic()}
async function addWeather(){if(!worldMap||worldMap.getLayer('weather-radar'))return;try{const d=await fetch('https://api.rainviewer.com/public/weather-maps.json').then(r=>r.json());const frame=d.radar?.past?.at(-1);if(!frame)return;worldMap.addSource('weather-radar',{type:'raster',tiles:[`${d.host}${frame.path}/256/{z}/{x}/{y}/2/1_1.png`],tileSize:256,maxzoom:7,attribution:'Weather data by RainViewer'});worldMap.addLayer({id:'weather-radar',type:'raster',source:'weather-radar',paint:{'raster-opacity':.58,'raster-fade-duration':0}})}catch(e){console.warn('Radar unavailable',e)}}

function initWorldAITraffic(){
  aiWorldMarkers.forEach(m=>m.remove());aiWorldMarkers=[];aiWorldFlights=[];
  if(!worldMap||WORLD_MAJOR_AIRPORTS.length<30)return;
  const names=['NOVA','ORBIT','AURORA','MERIDIAN','ATLAS','NORTHSTAR','SUNJET','BLUEWING','PACIFICA','CONTINENTAL'];
  const models=['A320neo','A321neo','B737 MAX','B787-9','A350-900','E195-E2','A330-900','B777-300ER'];
  for(let i=0;i<52;i++){
    const a=WORLD_MAJOR_AIRPORTS[(i*37+11)%WORLD_MAJOR_AIRPORTS.length],b=WORLD_MAJOR_AIRPORTS[(i*83+173)%WORLD_MAJOR_AIRPORTS.length];if(!a||!b||a.ident===b.ident)continue;
    const pts=gcPoints(a,b,72),el=document.createElement('div');el.className='world-ai-marker';el.textContent='✈';el.title=`${names[i%names.length]} ${100+i} · ${models[i%models.length]}`;
    const m=new maplibregl.Marker({element:el}).setLngLat(pts[0]).addTo(worldMap);aiWorldMarkers.push(m);aiWorldFlights.push({marker:m,pts,offset:(i*.071)%1,speed:.0000017+(i%9)*.00000015,name:names[i%names.length],model:models[i%models.length]})
  }
  const start=performance.now();function tick(t){if(!worldMap)return;aiWorldFlights.forEach((f,i)=>{const p=(f.offset+(t-start)*f.speed)%1,idx=Math.min(f.pts.length-2,Math.floor(p*(f.pts.length-1))),local=p*(f.pts.length-1)-idx,a=f.pts[idx],b=f.pts[idx+1];f.marker.setLngLat([a[0]+(b[0]-a[0])*local,a[1]+(b[1]-a[1])*local])});requestAnimationFrame(tick)}requestAnimationFrame(tick)
}

function syncWorldRoutes(){if(!worldMap||!worldMap.loaded()||!STATE)return;const features=[];STATE.routes.forEach(r=>{if(!r.origin_airport||!r.destination_airport)return;features.push({type:'Feature',geometry:{type:'LineString',coordinates:gcPoints(r.origin_airport,r.destination_airport,72)},properties:{kind:'own',id:r.id}});if(r.partner)features.push({type:'Feature',geometry:{type:'LineString',coordinates:gcPoints({lat:r.partner.from_lat,lon:r.partner.from_lon},{lat:r.partner.to_lat,lon:r.partner.to_lon},48)},properties:{kind:'partner',id:r.id}})});const hubFeatures=STATE.hubs.map(h=>({type:'Feature',geometry:{type:'Point',coordinates:[h.airport.lon,h.airport.lat]},properties:{ident:h.ident,code:h.airport.code,name:h.airport.name,type:h.airport.type,country:h.airport.country,municipality:h.airport.municipality||''}}));
 if(worldMap.getSource('routes'))worldMap.getSource('routes').setData({type:'FeatureCollection',features});else{worldMap.addSource('routes',{type:'geojson',data:{type:'FeatureCollection',features}});worldMap.addLayer({id:'routes-own',type:'line',source:'routes',filter:['==',['get','kind'],'own'],paint:{'line-color':STATE.profile.accent_color,'line-width':2.2,'line-opacity':.85}});worldMap.addLayer({id:'routes-partner',type:'line',source:'routes',filter:['==',['get','kind'],'partner'],paint:{'line-color':'#b587ff','line-width':2,'line-dasharray':[2,2],'line-opacity':.85}})}
 if(worldMap.getSource('owned-hubs'))worldMap.getSource('owned-hubs').setData({type:'FeatureCollection',features:hubFeatures});else{worldMap.addSource('owned-hubs',{type:'geojson',data:{type:'FeatureCollection',features:hubFeatures}});worldMap.addLayer({id:'owned-hubs',type:'circle',source:'owned-hubs',paint:{'circle-radius':['interpolate',['linear'],['zoom'],1,4,6,9],'circle-color':STATE.profile.accent_color,'circle-stroke-color':'#fff','circle-stroke-width':1.5}})}
}
function syncWorldAircraft(){if(!worldMap||!worldMap.loaded()||!STATE)return;const active=new Set();STATE.aircraft.forEach(a=>{if(!a.flight)return;active.add(a.id);let m=worldAircraftMarkers.get(a.id);if(!m){const el=document.createElement('button');el.className='aircraft-marker';el.innerHTML='✈';el.addEventListener('click',()=>inspectWorldAircraft(a.id));m=new maplibregl.Marker({element:el}).setLngLat([a.flight.lon,a.flight.lat]).addTo(worldMap);worldAircraftMarkers.set(a.id,m)}m.setLngLat([a.flight.lon,a.flight.lat]);m.getElement().style.transform=`rotate(${a.flight.heading||0}deg)`});for(const [id,m] of worldAircraftMarkers){if(!active.has(id)){m.remove();worldAircraftMarkers.delete(id)}}}
function inspectWorldAircraft(id){const a=STATE.aircraft.find(x=>x.id===id);if(!a)return;const f=a.flight;$('#worldInspectorContent').innerHTML=`<span class="inspector-tag">${a.tail}</span><h2 class="inspector-title">${a.spec.name}</h2><div class="stat-row"><span>Statut</span><b>${f?.status||'Disponible'}</b></div>${f?`<div class="stat-row"><span>Segment</span><b>${f.from} → ${f.to}</b></div><div class="stat-row"><span>Altitude</span><b>${fmt(f.altitude_ft)} ft</b></div><div class="stat-row"><span>Vitesse</span><b>${f.speed_kts} kt</b></div>`:''}<button class="primary" id="worldCockpit">Vue cockpit dynamique</button>`;$('#worldInspector').classList.add('open');$('#worldCockpit').addEventListener('click',()=>openCockpit(id))}
async function inspectWorldAirport(props){try{const a=await api('/api/airports/'+encodeURIComponent(props.ident));const owned=STATE.hubs.some(h=>h.ident===a.ident);$('#worldInspectorContent').innerHTML=`<span class="inspector-tag">AÉROPORT</span><h2 class="inspector-title">${a.code} · ${a.name}</h2><p class="muted">${a.municipality||''} · ${a.country}</p><div class="stat-row"><span>Pistes</span><b>${a.runway_count}</b></div><div class="stat-row"><span>Plus longue</span><b>${Math.round(a.longest_runway_ft*.3048)} m</b></div><div class="stat-row"><span>Statut</span><b>${owned?'Hub possédé':money(a.price)}</b></div>${owned?`<button class="primary" id="goWorldHub">Ouvrir ce hub</button>`:`<button class="primary" id="buyWorldHub">Acheter comme hub</button>`}`;$('#worldInspector').classList.add('open');if(owned)$('#goWorldHub').addEventListener('click',()=>{activeHubIdent=a.ident;renderHubSelector();loadHub(a.ident);nav('hub')});else $('#buyWorldHub').addEventListener('click',()=>buyHub(a.ident))}catch(e){toast(e.message)}}
$('#weatherToggle').addEventListener('click',e=>{weatherEnabled=!weatherEnabled;e.currentTarget.classList.toggle('active',weatherEnabled);if(worldMap.getLayer('weather-radar'))worldMap.setLayoutProperty('weather-radar','visibility',weatherEnabled?'visible':'none')});$('#airportToggle').addEventListener('click',e=>{airportLayerEnabled=!airportLayerEnabled;e.currentTarget.classList.toggle('active',airportLayerEnabled);if(worldMap.getLayer('major-airports'))worldMap.setLayoutProperty('major-airports','visibility',airportLayerEnabled?'visible':'none')});$('#routesToggle').addEventListener('click',e=>{routesEnabled=!routesEnabled;e.currentTarget.classList.toggle('active',routesEnabled);['routes-own','routes-partner'].forEach(id=>worldMap.getLayer(id)&&worldMap.setLayoutProperty(id,'visibility',routesEnabled?'visible':'none'))});$('#spinGlobe').addEventListener('click',e=>{e.currentTarget.classList.toggle('active');if(spinTimer){clearInterval(spinTimer);spinTimer=null}else spinTimer=setInterval(()=>{if(worldMap&&document.querySelector('[data-view="world"]').classList.contains('active'))worldMap.easeTo({center:[worldMap.getCenter().lng+.7,worldMap.getCenter().lat],duration:500,easing:t=>t})},500)});

// ---------- HUBS ----------
function renderOwnedHubs(){if(!STATE)return;$('#ownedHubs').innerHTML=STATE.hubs.map(h=>`<div class="list-row"><div><b>${h.airport.code} · ${h.airport.name}</b><small>${h.airport.municipality||''} · Niveau ${h.level}${h.is_primary?' · HUB PRINCIPAL':''}</small></div><div class="list-actions"><button class="mini-btn" onclick="openOwnedHub('${h.ident}')">Vue aérienne</button>${h.is_primary?'':`<button class="mini-btn" onclick="makePrimary('${h.ident}')">Principal</button>`}</div></div>`).join('')}
window.openOwnedHub=ident=>{activeHubIdent=ident;renderHubSelector();loadHub(ident);nav('hub')};window.makePrimary=async ident=>{try{await api('/api/hubs/primary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ident})});toast('Hub principal modifié');await loadState()}catch(e){toast(e.message)}};
const searchHub=debounce(async()=>{const q=$('#hubSearch').value.trim();if(q.length<2){$('#hubSearchResults').innerHTML='';return}const items=await api('/api/airports/search?q='+encodeURIComponent(q)+'&limit=35');$('#hubSearchResults').innerHTML=items.map(a=>`<button class="search-result" data-ident="${a.ident}"><span><b>${a.code} · ${a.name}</b><span>${a.municipality||''} · ${a.country}</span></span></button>`).join('');$('#hubSearchResults').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>previewExtraHub(b.dataset.ident)))},220);$('#hubSearch').addEventListener('input',searchHub);
async function previewExtraHub(ident){extraHubSelected=await api('/api/airports/'+encodeURIComponent(ident));$('#hubPurchasePreview').classList.remove('empty');$('#hubPurchasePreview').innerHTML=`<b>${extraHubSelected.code} · ${extraHubSelected.name}</b><span>${extraHubSelected.municipality||''} · ${extraHubSelected.country} · ${extraHubSelected.runway_count} piste(s)</span><span><strong>${money(extraHubSelected.price)}</strong></span>`;$('#buyExtraHub').disabled=STATE.hubs.some(h=>h.ident===extraHubSelected.ident)||!extraHubSelected.purchasable}
async function buyHub(ident){try{await api('/api/hubs/buy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ident})});toast('Nouveau hub acquis');await loadState();renderOwnedHubs();nav('hubs')}catch(e){toast(e.message)}}$('#buyExtraHub').addEventListener('click',()=>extraHubSelected&&buyHub(extraHubSelected.ident));

// ---------- MARKET ----------
async function loadMarket(reset=true){if(reset){marketOffset=0;$('#marketGrid').innerHTML=''}const params=new URLSearchParams({q:marketQuery,manufacturer:marketManufacturer,commercial_only:String(marketCommercial),limit:'48',offset:String(marketOffset)});const d=await api('/api/aircraft/catalog?'+params);if(reset&&$('#manufacturerFilter').options.length===1)d.manufacturers.forEach(m=>$('#manufacturerFilter').insertAdjacentHTML('beforeend',`<option>${m}</option>`));renderMarketCards(d.items);marketOffset+=d.items.length;$('#loadMoreAircraft').style.display=d.items.length<48?'none':'block'}
function renderMarketCards(items){const g=$('#marketGrid');items.forEach(a=>{const c=document.createElement('article');c.className='aircraft-card';c.innerHTML=`<header><div><span class="manufacturer">${a.manufacturer}</span><h3>${a.name}</h3></div><span class="code-pill">${a.icao}${a.iata?' · '+a.iata:''}</span></header><div class="spec-grid"><div><small>SIÈGES SIM.</small><b>${a.seats}</b></div><div><small>AUTONOMIE</small><b>${fmt(a.range_km)} km</b></div><div><small>CROISIÈRE</small><b>${a.cruise_kts} kt</b></div><div><small>MTOW</small><b>${a.mtow_kg?fmt(Math.round(a.mtow_kg/1000))+' t':'—'}</b></div><div><small>PISTE EST.</small><b>${a.runway_required_m?a.runway_required_m+' m':'VTOL'}</b></div><div><small>CATÉGORIE</small><b>${a.category}</b></div></div><div class="price-row"><strong>${money(a.price)}</strong><button class="mini-btn">Voir / acquérir</button></div>`;c.querySelector('button').addEventListener('click',()=>openAircraftModal(a.icao));g.appendChild(c)})}
async function openAircraftModal(code){const a=await api('/api/aircraft/catalog/'+code);const hubs=STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('');$('#aircraftModalContent').innerHTML=`<p class="eyebrow">${a.manufacturer.toUpperCase()}</p><h1>${a.name}</h1><p class="muted">ICAO ${a.icao}${a.iata?' · IATA '+a.iata:''} · ${a.category}</p><div class="spec-grid"><div><small>Capacité sim.</small><b>${a.seats}</b></div><div><small>Autonomie</small><b>${fmt(a.range_km)} km</b></div><div><small>Croisière</small><b>${a.cruise_kts} kt</b></div><div><small>Plafond</small><b>${a.service_ceiling?fmt(a.service_ceiling)+' ft':'—'}</b></div><div><small>Longueur</small><b>${a.length_m?a.length_m+' m':'—'}</b></div><div><small>Envergure</small><b>${a.wingspan_m?a.wingspan_m+' m':'—'}</b></div></div><label>Base d’affectation<select id="buyHomeHub">${hubs}</select></label>${a.models?.length?`<label>Variante / motorisation<select id="buyVariant"><option value="">Type générique</option>${a.models.slice(0,80).map(m=>`<option value="${m.name}">${m.name} · ${m.engine_manufacturer||''} ${m.engine_model||''}</option>`).join('')}</select></label>`:''}<div class="price-row"><strong>Achat ${money(a.price)}</strong><strong>Leasing ${money(a.lease)}</strong></div><div class="form-two"><button class="primary" id="buyPlaneCash">Acheter</button><button class="secondary" id="buyPlaneLease">Louer</button></div><p class="data-note">Les identités/dimensions proviennent du catalogue aéronautique embarqué. Les valeurs économiques et certaines performances manquantes sont des valeurs de simulation.</p>`;$('#aircraftModal').classList.add('open');$('#buyPlaneCash').addEventListener('click',()=>buyAircraft(a,'buy'));$('#buyPlaneLease').addEventListener('click',()=>buyAircraft(a,'lease'))}
async function buyAircraft(a,mode){try{const home=$('#buyHomeHub').value,variant=$('#buyVariant')?.value||'';const d=await api('/api/aircraft/buy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type_icao:a.icao,acquisition:mode,home_hub:home,model_variant:variant})});toast(`${d.tail} ajouté à la flotte`);$('#aircraftModal').classList.remove('open');await loadState();nav('fleet')}catch(e){toast(e.message)}}
$('#aircraftSearch').addEventListener('input',debounce(e=>{marketQuery=e.target.value;loadMarket(true)},260));$('#manufacturerFilter').addEventListener('change',e=>{marketManufacturer=e.target.value;loadMarket(true)});$('#commercialOnly').addEventListener('change',e=>{marketCommercial=e.target.checked;loadMarket(true)});$('#loadMoreAircraft').addEventListener('click',()=>loadMarket(false));

// ---------- FLEET & LIVERY ----------
function renderFleet(){if(!STATE)return;const b=$('#fleetList');if(!STATE.aircraft.length){b.innerHTML='<div class="empty-state"><b>Ta flotte est vide</b><span>Va dans Aéronefs pour acheter ou louer ton premier appareil.</span></div>';return}b.innerHTML=STATE.aircraft.map(a=>`<article class="fleet-item"><div class="fleet-plane-icon" style="color:${a.livery.accent}">✈</div><div><b>${a.tail} · ${a.spec.manufacturer} ${a.spec.name}</b><small>${a.home_hub} · ${a.model_variant||a.spec.icao} · État ${a.condition}% · ${a.flight?a.flight.status:'Disponible'}</small></div><div class="fleet-actions">${a.flight?`<button class="mini-btn" onclick="openCockpit(${a.id})">Cockpit</button>`:''}<button class="mini-btn" onclick="editLivery(${a.id})">Livrée</button></div></article>`).join('')}
window.editLivery=id=>{const a=STATE.aircraft.find(x=>x.id===id);if(!a)return;$('#liveryModalContent').innerHTML=`<p class="eyebrow">${a.tail}</p><h2>Personnaliser la livrée</h2><div class="color-grid"><label>Principal<input type="color" id="lp" value="${a.livery.primary}"></label><label>Secondaire<input type="color" id="ls" value="${a.livery.secondary}"></label><label>Accent<input type="color" id="la" value="${a.livery.accent}"></label></div><label>Style<select id="lt"><option value="swoosh">Swoosh</option><option value="tail">Dérive forte</option><option value="stripe">Bande</option><option value="minimal">Minimal</option><option value="retro">Rétro</option></select></label><label>Nom de la livrée<input id="ln" value="${a.livery.name||'Standard'}"></label><button class="primary" id="saveLivery">Appliquer à ${a.tail}</button>`;$('#lt').value=a.livery.template;$('#liveryModal').classList.add('open');$('#saveLivery').addEventListener('click',async()=>{try{await api(`/api/aircraft/${id}/livery`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({primary:$('#lp').value,secondary:$('#ls').value,accent:$('#la').value,template:$('#lt').value,name:$('#ln').value})});toast('Livrée enregistrée');$('#liveryModal').classList.remove('open');await loadState()}catch(e){toast(e.message)}})};

// ---------- ROUTES ----------
function renderRoutes(){if(!STATE)return;$('#routeOrigin').innerHTML=STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('');const used=new Set(STATE.routes.map(r=>r.aircraft_id));const free=STATE.aircraft.filter(a=>!used.has(a.id));$('#routeAircraft').innerHTML='<option value="">Choisir…</option>'+free.map(a=>`<option value="${a.id}">${a.tail} · ${a.spec.name}</option>`).join('');const list=$('#routesList');if(!STATE.routes.length){list.innerHTML='<div class="empty-state"><b>Aucune rotation</b><span>Crée ta première ligne avec un avion libre.</span></div>';return}list.innerHTML=STATE.routes.map(r=>`<div class="list-row"><div><b>${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${r.tail} · ${r.model} · ${r.flight.status} · ${fmt(r.flight.distance_km)} km</small>${r.partner?`<small class="partner-line">Ton vol ${r.origin_airport.code} → ${r.destination_airport.code}, puis ${r.partner.airline} ${r.partner.from} → ${r.partner.to}</small>`:''}</div><div class="list-actions"><button class="mini-btn" onclick="openCockpit(${r.aircraft_id})">Cockpit</button><button class="mini-btn danger-btn" onclick="deleteRoute(${r.id})">Fermer</button></div></div>`).join('')}
const routeDestSearch=debounce(async()=>{const q=$('#routeDestinationSearch').value.trim();if(q.length<2){$('#routeDestinationResults').innerHTML='';return}const items=await api('/api/airports/search?q='+encodeURIComponent(q)+'&limit=30');$('#routeDestinationResults').innerHTML=items.map(a=>`<button type="button" class="search-result" data-ident="${a.ident}"><span><b>${a.code} · ${a.name}</b><span>${a.municipality||''} · ${a.country}</span></span></button>`).join('');$('#routeDestinationResults').querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{routeDestination=await api('/api/airports/'+b.dataset.ident);$('#routeDestination').value=routeDestination.ident;$('#routeDestinationSearch').value=`${routeDestination.code} · ${routeDestination.name}`;$('#routeDestinationResults').innerHTML='';checkRoute()}))},230);$('#routeDestinationSearch').addEventListener('input',routeDestSearch);$('#routeOrigin').addEventListener('change',checkRoute);$('#routeAircraft').addEventListener('change',checkRoute);
async function checkRoute(){const ac=$('#routeAircraft').value,origin=$('#routeOrigin').value,dest=$('#routeDestination').value,box=$('#routeCheck');$('#acceptAltWrap').classList.add('hidden');$('#acceptAlternative').checked=false;if(!ac||!origin||!dest){box.className='route-check';box.textContent='Choisis un avion et une destination.';return}try{const d=await api(`/api/route-check?origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(dest)}&aircraft_id=${ac}`);box.className='route-check '+(d.ok?'ok':'bad');box.innerHTML=d.ok?`✓ ${d.reason}`:`⚠ ${d.reason}${d.alternative?`<br><b>OPS :</b> ${d.alternative.text}`:''}`;if(d.alternative)$('#acceptAltWrap').classList.remove('hidden')}catch(e){box.className='route-check bad';box.textContent=e.message}}
$('#routeForm').addEventListener('submit',async e=>{e.preventDefault();const body={aircraft_id:Number($('#routeAircraft').value),origin:$('#routeOrigin').value,destination:$('#routeDestination').value,frequency:Number($('#routeFreq').value),accept_alternative:$('#acceptAlternative').checked};if(!body.aircraft_id||!body.destination)return toast('Sélectionne un avion et une destination.');const r=await fetch('/api/routes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok){$('#routeCheck').className='route-check bad';$('#routeCheck').innerHTML=`⚠ ${d.check?.reason||d.detail||'Route impossible'}${d.check?.alternative?`<br><b>OPS :</b> ${d.check.alternative.text}`:''}`;if(d.check?.alternative)$('#acceptAltWrap').classList.remove('hidden');return}toast(d.alternative?'Itinéraire partenaire créé':'Rotation créée');routeDestination=null;$('#routeDestination').value='';$('#routeDestinationSearch').value='';await loadState();nav('world')});window.deleteRoute=async id=>{if(!confirm('Fermer cette rotation et libérer l’avion ?'))return;try{await api('/api/routes/'+id,{method:'DELETE'});toast('Rotation fermée');await loadState()}catch(e){toast(e.message)}};

// ---------- IDENTITY ----------
function syncIdentity(){if(!STATE)return;$('#logoText').value=STATE.profile.logo_text;$('#primaryColor').value=STATE.profile.primary_color;$('#secondaryColor').value=STATE.profile.secondary_color;$('#accentColor').value=STATE.profile.accent_color;$('#liveryTemplate').value=STATE.profile.livery_template;logoData=STATE.profile.logo_data||'';updateLiveryPreview()}
function updateLiveryPreview(){const p=$('#companyLiveryPreview');if(!p)return;p.style.setProperty('--livery-primary',$('#primaryColor').value);p.style.setProperty('--livery-secondary',$('#secondaryColor').value);p.style.setProperty('--livery-accent',$('#accentColor').value);$('#previewLogo').textContent=$('#logoText').value||'SKYLINE'}['logoText','primaryColor','secondaryColor','accentColor','liveryTemplate'].forEach(id=>$('#'+id).addEventListener('input',updateLiveryPreview));$('#logoFile').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(f.size>700000){toast('Logo trop lourd : 700 ko maximum');e.target.value='';return}const rd=new FileReader();rd.onload=()=>logoData=rd.result;rd.readAsDataURL(f)});$('#identityForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({primary_color:$('#primaryColor').value,secondary_color:$('#secondaryColor').value,accent_color:$('#accentColor').value,logo_text:$('#logoText').value,logo_data:logoData,livery_template:$('#liveryTemplate').value})});toast('Identité enregistrée');await loadState()}catch(e){toast(e.message)}});

// ---------- COCKPIT DYNAMIC ----------
function ensureCockpitMap(){if(cockpitMap)return;cockpitMap=new maplibregl.Map({container:'cockpitMap',style:SAT_STYLE,center:[2.5,49],zoom:8,pitch:78,bearing:0,interactive:false,attributionControl:true,maxPitch:85});cockpitMap.on('load',()=>cockpitMap.setProjection({type:'globe'}))}
window.openCockpit=id=>{selectedAircraft=id;ensureCockpitMap();$('#cockpitModal').classList.add('open');updateCockpit(true)};$('#closeCockpit').addEventListener('click',()=>{$('#cockpitModal').classList.remove('open');selectedAircraft=null});
let lastWeatherAt=0,stormy=false;async function updateCockpit(force=false){if(!selectedAircraft||!STATE)return;const a=STATE.aircraft.find(x=>x.id===selectedAircraft);if(!a)return;const f=a.flight;$('#cpAircraft').textContent=`${a.tail} · ${a.spec.name}`;if(!f){$('#cpFlight').textContent='AU SOL';$('#cpAlt').textContent='0 ft';$('#cpSpeed').textContent='0 kt';$('#cpHeading').textContent='—';$('#cpFuel').textContent='100%';$('#cpStatus').textContent='Disponible';return}$('#cpFlight').textContent=`${f.from} → ${f.to}`;$('#cpAlt').textContent=fmt(f.altitude_ft)+' ft';$('#cpSpeed').textContent=f.speed_kts+' kt';$('#cpHeading').textContent=Math.round(f.heading)+'°';$('#cpFuel').textContent=f.fuel_percent+'%';$('#cpStatus').textContent=f.status;if(cockpitMap&&cockpitMap.loaded()){const z=f.airborne?Math.max(4.5,Math.min(9,8.4-f.altitude_ft/12000)):14;cockpitMap.easeTo({center:[f.lon,f.lat],bearing:f.heading,pitch:f.airborne?78:58,zoom:z,duration:force?0:1200,easing:t=>t})}const now=Date.now();if(force||now-lastWeatherAt>90000){lastWeatherAt=now;try{const w=await api(`/api/weather/current?lat=${f.lat}&lon=${f.lon}`);const c=w.current||{},cloud=Number(c.cloud_cover||0),prec=Number(c.precipitation||0),code=Number(c.weather_code||0);$('#cpWeather').textContent=w.ok?`${Math.round(cloud)}% nuages · ${Math.round(c.wind_speed_10m||0)} kt`:'Indispo';$('#cockpitClouds').style.opacity=Math.min(.82,.08+cloud/125);stormy=code>=95||prec>=3;if(stormy)triggerStorm()}catch{$('#cpWeather').textContent='Indispo'}}}
function triggerStorm(){if(!stormy)return;$('#stormFlash').classList.remove('flash');void $('#stormFlash').offsetWidth;$('#stormFlash').classList.add('flash');setTimeout(()=>stormy&&triggerStorm(),4500+Math.random()*6000)}

